_CODES = MappingProxyType({code: (severity, meaning) for code, severity, meaning in _ROWS})


def known_codes():
    return tuple(sorted(_CODES))


def code_metadata(code):
    if type(code) is not str:
        raise TypeError("A code must be a string")
    row = _CODES.get(code)
    return None if row is None else {"code": code, "default_severity": row[0],
                                   "meaning": row[1], "catalog_version": CATALOG_VERSION}


